content.text:
{
  "name": "树莓派 PiOLED 显示屏",
  "name_en": "PiOLED Display",
  "manufacturer": "Adafruit",
  "description": "一款用于树莓派的小型单色 OLED 显示屏，可在实验装置上本地显示运行状态、传感器读数和简短提示信息。",
  "description_en": "A small monochrome OLED display for Raspberry Pi, used to show local system status, sensor readings, and short messages on laboratory setups.",
  "actions": [
    {
      "action_name": "auto-lcd_init",
      "description": "初始化显示屏",
      "description_en": "Initialize the display"
    },
    {
      "action_name": "auto-lcd_write_lines",
      "description": "将多行文本写入显示屏",
      "description_en": "Write multiple lines of text to the display"
    },
    {
      "action_name": "auto-lcd_backlight",
      "description": "设置显示背光状态（该设备通常不支持）",
      "description_en": "Set the display backlight state (typically not supported on this device)"
    }
  ],
  "tag_hints": [
    "OLED display",
    "Raspberry Pi",
    "local status display",
    "instrument readout",
    "I2C display"
  ]
}

